local L=TranquilityLFG
L.discordInvite="https://discord.gg/CMjbSRYt6"
function L:MirrorDB()
 self:Settings();self.db.mirror=self.db.mirror or {relay="",channels={},messages={},outbox={}};return self.db.mirror
end
function L:StoreMirror(row)
 local db=self:MirrorDB()
 for _,old in ipairs(db.messages)do if old.id==row.id then return false end end
 db.messages[#db.messages+1]=row;while #db.messages>120 do table.remove(db.messages,1)end;return true
end
-- A trusted officer imports flat, bounded rows generated by the existing bot companion.
-- WoW never evaluates downloaded Lua/JSON or opens an HTTP/socket connection.
function L:ImportDiscord(text)
 local db=self:MirrorDB()
 if self:Key(db.relay)~=self:Key(self:Me())or not self:Allowed()or type(text)~="string"or #text>16000 then return false end
 local accepted=0
 for line in text:gmatch("[^\r\n]+")do
  local a={};for v in (line.."|"):gmatch("(.-)|")do a[#a+1]=v end
  if a[1]=="DA2"and #a==6 and a[2]:match("^[%d%-]+$")and #a[2]<=40 and self:Clean(a[3],100)and db.channels[a[4]]and a[5]:match("^%d+$")and #a[5]<=24 and self:Int(a[6],0,9999999999)then
   if #line<=240 and #self.queue<45 then self:ApplyDiscordAck(a);self:Send(a);accepted=accepted+1 end
  elseif a[1]=="DC2"and #a==7 and a[2]:match("^%d+$")and #a[2]<=24 and self:Clean(a[3],32)and self:Clean(a[4],40)and self:Clean(a[5],120)and self:Int(a[6],0,9999999999)and a[7]=="PUBLIC"then
   if math.abs(self:Clock()-tonumber(a[6]))<=7*86400 and db.channels[a[3]]then
    local packet={"DC2",a[2],a[3],a[4],a[5],a[6],"PUBLIC"}
    if #table.concat(packet,"|")<=240 and #self.queue<45 then
     if self:StoreMirror({id=a[2],channel=a[3],author=a[4],text=a[5],at=tonumber(a[6]),source="Discord snapshot"})then self:Send(packet);accepted=accepted+1 end
    end
   end
  end
 end
 self:Notify("Imported "..accepted.." Discord snapshot messages. Live delivery requires the trusted relay's explicit handoff.");return accepted
end
function L:ApplyDiscordAck(a)
 local db=self:MirrorDB()
 for _,r in ipairs(db.outbox)do if r.id==a[2]and self:Key(r.author)==self:Key(a[3])and r.channel==a[4]then r.status="Posted to Discord";r.discordID=a[5];r.postedAt=tonumber(a[6])end end
end
function L:ReplyDiscord(channel,text)
 local db=self:MirrorDB()
 if not self:Allowed()or not db.channels[channel]or not self:Clean(text,120)or db.relay==""or #db.outbox>=100 then return false end
 if self:Clock()-(self.discordReplyAt or 0)<5 then return false end
 self.discordReplyAt=self:Clock();self.db.replySerial=(self.db.replySerial or 0)+1
 local id=tostring(self:Clock()).."-"..self.db.replySerial
 db.outbox[#db.outbox+1]={id=id,channel=channel,author=self:Me(),text=text,at=self:Clock(),status="Queued to relay; NOT posted to Discord"}
 self:Send({"DR2",id,channel,text,tostring(self:Clock())});self:Notify("Reply queued for officer/bot handoff. Not yet posted to Discord.");return true
end
function L:DiscordReplyExport()
 local db=self:MirrorDB();if self:Key(db.relay)~=self:Key(self:Me())then return ""end
 local out={}
 for _,r in ipairs(db.outbox)do if r.status~="Posted to Discord"then out[#out+1]=table.concat({"DR2",r.id,r.channel,r.author,r.text,tostring(r.at)},"|")end end
 return table.concat(out,"\n")
end
local receive=L.Receive
function L:Receive(text,sender,channel)
 if not self:Allowed()or channel~="GUILD"or not self:Clean(sender,100)or type(text)~="string"or #text>240 or text:find("[%c]")then return end
 local a={};for s in (text.."|"):gmatch("(.-)|")do a[#a+1]=s end
 if a[1]=="DA2"then
  local db=self:MirrorDB();local at=self:Int(a[6],0,9999999999)
  if #a~=6 or self:Key(sender)~=self:Key(db.relay)or not at or at>self:Clock()+60 or not db.channels[a[4]]or not a[5]:match("^%d+$")or #a[5]>24 then return end
  self:ApplyDiscordAck(a);self:Refresh();return
 elseif a[1]=="DC2"then
  local db=self:MirrorDB();local at=self:Int(a[6],0,9999999999)
  if #a~=7 or self:Key(sender)~=self:Key(db.relay)or not a[2]:match("^%d+$")or #a[2]>24 or not db.channels[a[3]]or not self:Clean(a[4],40)or not self:Clean(a[5],120)or not at or math.abs(self:Clock()-at)>7*86400 or a[7]~="PUBLIC"then return end
  self:StoreMirror({id=a[2],channel=a[3],author=a[4],text=a[5],at=at,source="Trusted relay snapshot"});self:Refresh();return
 elseif a[1]=="DR2"then
  local db=self:MirrorDB();local at=self:Int(a[5],0,9999999999)
  if #a~=5 or self:Key(self:Me())~=self:Key(db.relay)or not db.channels[a[3]]or not a[2]:match("^[%d%-]+$")or #a[2]>40 or not self:Clean(a[4],120)or not at or math.abs(self:Clock()-at)>120 or #db.outbox>=100 then return end
  for _,r in ipairs(db.outbox)do if r.id==a[2]and self:Key(r.author)==self:Key(sender)then return end end
  db.outbox[#db.outbox+1]={id=a[2],channel=a[3],author=sender,text=a[4],at=at,status="Received by relay; NOT posted to Discord"};self:Refresh();return
 end
 receive(self,text,sender,channel)
end
